    [7677]={name="White Stallion Exchange",questLevel=1,requiredLevel=60,faction="Alliance",objective="If you bring me your white stallion, I'll trade you for one from the new herd. The new horse will be just as fast as your old one, but have a different look to it. You can look at the swift steeds here to see what it will look like.\n\nMUST PAY 500 Gold too....",rewards={{18776,1},{18777,1},{18778,1}},startName="Katie Hunter",startLocation="Elwynn Forest",turninName="Katie Hunter",turninLocation="Elwynn Forest"},
