    [7828]={name="Stalking the Stalkers",questLevel=48,requiredLevel=44,faction="Horde",objective="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Silvermane Stalkers and 10 Silvermane Howlers. Return to him once the task is complete.\n\nMarkhor mentioned that the wolves hide in the wilds of the Hinterlands.",startName="Huntsman Markhor",startLocation="The Hinterlands",turninName="Huntsman Markhor",turninLocation="The Hinterlands"},
    [7829]={name="Hunt the Savages",questLevel=48,requiredLevel=44,faction="Horde",objective="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.\n\nMarkhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands.",startName="Huntsman Markhor",startLocation="The Hinterlands",turninName="Huntsman Markhor",turninLocation="The Hinterlands"},
    [7830]={name="Avenging the Fallen",questLevel=48,requiredLevel=44,faction="Horde",objective="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.\n\nMarkhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands.",startName="Huntsman Markhor",startLocation="The Hinterlands",turninName="Huntsman Markhor",turninLocation="The Hinterlands"},
