    [8304]={name="Dearest Natalia",questLevel=60,requiredLevel=58,faction="Both",objective="Commander Mar'alith at Cenarion Hold in Silithus wants you to question the inhabitants of Bronzebeard's Encampment. You will find Bronzebeard's Encampment south of Cenarion Hold.\n\nOnce you have gathered the requested information, return to Commander Mar'alith.",startName="Commander Mar'alith",startLocation="Silithus",turninName="Commander Mar'alith",turninLocation="Silithus"},
